<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/app/bootstrap.php';require APP_ROOT.'/app/OrderStore.php';require APP_ROOT.'/app/AlipayClient.php';
if($_SERVER['REQUEST_METHOD']!=='POST')json_response(['ok'=>false,'message'=>'仅支持 POST'],405);$c=load_config();if(!ready($c))json_response(['ok'=>false,'message'=>'请先填写支付宝配置'],400);$in=json_decode((string)file_get_contents('php://input'),true);if(!is_array($in))$in=$_POST;$subject=trim((string)($in['subject']??'支付宝扫码测试订单'));$raw=trim((string)($in['amount']??'0.01'));if(!preg_match('/^\d{1,8}(?:\.\d{1,2})?$/',$raw))json_response(['ok'=>false,'message'=>'金额格式错误'],400);$amount=number_format((float)$raw,2,'.','');if((float)$amount<0.01)json_response(['ok'=>false,'message'=>'金额不能低于 0.01 元'],400);$no='T'.date('YmdHis').strtoupper(bin2hex(random_bytes(4)));OrderStore::create(['order_no'=>$no,'subject'=>$subject?:'支付宝扫码测试订单','amount'=>$amount,'status'=>'WAITING']);try{$client=new AlipayClient($c);$r=$client->precreate($no,$amount,$subject?:'支付宝扫码测试订单');if(($r['code']??'')!=='10000'||empty($r['qr_code'])){OrderStore::update($no,['status'=>'CREATE_FAILED','error'=>$r['sub_msg']??$r['msg']??'创建失败']);json_response(['ok'=>false,'message'=>$r['sub_msg']??$r['msg']??'支付宝创建失败','code'=>$r['sub_code']??$r['code']??'','order_no'=>$no],400);}OrderStore::update($no,['qr_code'=>$r['qr_code']]);log_event('ORDER_CREATED',['order_no'=>$no,'amount'=>$amount]);json_response(['ok'=>true,'order_no'=>$no,'amount'=>$amount,'subject'=>$subject,'qr_code'=>$r['qr_code']]);}catch(Throwable $e){OrderStore::update($no,['status'=>'CREATE_FAILED','error'=>$e->getMessage()]);log_event('CREATE_ERROR',['order_no'=>$no,'error'=>$e->getMessage()]);json_response(['ok'=>false,'message'=>$e->getMessage(),'order_no'=>$no],500);}